sys_script_include.script:
var VendorUtils = Class.create();
VendorUtils.prototype = {
    initialize: function() {
    },

    // 1. Fetch vendor details by vendor number
    getVendorDetailsByID: function(vendorID) {
        var gr = new GlideRecord('x_1790116_event_ma_vendor');
        gr.addQuery('number', vendorID);
        gr.query();
        if (gr.next()) {
            return gr.u_vendor_name + ' | ' + gr.u_email + ' | ' + gr.u_service_type + ' | ' + gr.u_available;
        }
        return 'Vendor not found';
    },

    // 2. Check if a vendor is available
    isVendorAvailable: function(vendorID) {
        var gr = new GlideRecord('x_1790116_event_ma_vendor');
        gr.addQuery('number', vendorID);
		gr.addQuery('u_available','=','true');
        gr.query();
        if (gr.next()) {
            return'Vendor is available' ;
        }
        return 'Vendor not found';
    },

    // 3. Fetch vendors by event ID
    getVendorsByEvent: function(eventID) {
        var gr = new GlideRecord('x_1790116_event_ma_vendor');
        gr.addQuery('u_event_id.number', eventID);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.u_vendor_name + ' | ' + gr.u_email + ' | ' + gr.u_service_type);
        }
        return result.length ? result.join('\n') : 'No vendors found for this event';
    },

    type: 'VendorUtils'
};
